theme.css:
/* Editorial by HTML5 UP | html5up.net | @ajlkn | CC BY 3.0.
 * Adapted for ImmichPager; composition, typography and accessibility modified. */
:scope { grid-template-columns:300px minmax(0,1fr); gap:48px; }
.ip-hero { background:#f5f6f7; padding:24px; border-top:5px solid #f56a6a; }
.ip-title { font-weight:var(--pager-title-font-weight); letter-spacing:-.02em; }
.ip-navigation { text-transform:uppercase; font-size:.75rem; }
.ip-block { padding-block:32px; border-bottom:1px solid #d8dee1; }
.ip-block .block-heading { font-family:var(--pager-heading-font); border-bottom:3px solid #f56a6a; padding-bottom:12px; width:fit-content; max-width:100%; }
@media(max-width:760px) { :scope { display:block; padding:20px; } .ip-hero { padding:24px; } }

.ip-description { opacity:1; }

.ip-albums:not(.tiles) .ip-album-info p { opacity:1; color:var(--pager-muted); }
.ip-albums.tiles .ip-album-info p { opacity:1; color:#ffffff; }
